import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 * @property {any} [textContent]
 * @property {any} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} primitives
 * @property {Function} emit
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Create root group
  const root = new Group();

  // Plane size based on image aspect (512x320 -> 1.6:1)
  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ map: null, transparent: true });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply cinematic primitives
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const result = fn(mesh, prim.params);
        if (result && typeof result.cleanup === 'function') {
          primitiveCleanups.push(result.cleanup);
        }
      }
    }
  }

  // Hover rise‑in animation (0.15 scene units)
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(mesh.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });

  // Event handlers exposed via userData
  root.userData.handlers = {
    hoverEnter: () => hoverTl.play(),
    hoverLeave: () => hoverTl.reverse(),
    click: () => ctx.emit('hub-journal.select', {}),
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    hoverTl.kill();
    primitiveCleanups.forEach((fn) => fn());
    geometry.dispose();
    material.dispose();
    // texture is managed by the loader cache; do not dispose here
  };

  return root;
}
